room.on('begin',()=>{net.locked=true;});
net.on('leave',entry=>{
const m=room.memberAt(entry.seat);
if(m)m.alive=false;
room.pushRoster();
room.fire('left',entry.seat);
});
net.on('msg',(seat,msg)=>room.receive(seat,msg));
net.on('error',err=>room.fire('error',err));
