if(p.k!=='mv'||e.over)return;
if(from!==e.turn)return;
if(p.i!==e.history.length){room.post({k:'state',history:e.history.slice()});return;}
const move=Object.assign({},p.move);
const at=e.history.length;
if(!e.apply(move))return;
