c.fillStyle='rgba(255,255,255,0.92)';
rr(c,cx-bw/2-3,y-bh/2-3,bw+6,bh+6,(bh+6)/2);c.fill();
c.fillStyle='rgba(30,50,80,0.25)';
rr(c,cx-bw/2,y-bh/2,bw,bh,bh/2);c.fill();
