const need=l=>900+220*(l-1);
function rankOf(xp){
let l=1,left=Math.max(0,Math.floor(xp||0));
while(l<MAX_RANK&&left>=need(l)){left-=need(l);l++;}
return{level:l,into:l>=MAX_RANK?need(l):left,need:need(l),title:Math.min(9,Math.floor((l-1)/6))};
}
