if(tex[k])return tex[k];
const m=D.MATS[k]||D.MATS.white,n=m.res,px=D.texels(k),rgba=new Uint8Array(n*n*4);
for(let i=0;i<n*n;i++){rgba[i*4]=px[i*3];rgba[i*4+1]=px[i*3+1];rgba[i*4+2]=px[i*3+2];rgba[i*4+3]=255;}
