if(g.phase==='result'){
setPaint(false);setPoses(false);free=false;
if(!racing&&!bank){bank=PV.HideMeta.bank(meta,g);meta=PV.HideMeta.load();}
panels.showResults(true,g,racing?null:bank);
}
